import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = os.environ.get('DB_PATH', '/data/app.db')
SECRET = os.environ.get('APP_SECRET', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY, username TEXT, email TEXT, role TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY, owner_id INTEGER, title TEXT,
        content TEXT, classification TEXT)''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT, action TEXT,
        user_id INTEGER, resource TEXT, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP)''')
    db.commit()
    db.close()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('X-Auth-Token', '')
        # Token format: user_id:hmac(user_id, secret)
        parts = token.split(':')
        if len(parts) != 2:
            return jsonify({'error': 'unauthorized'}), 401
        uid, sig = parts
        expected = hashlib.sha256(f"{uid}:{SECRET}".encode()).hexdigest()[:16]
        if sig != expected:
            return jsonify({'error': 'unauthorized'}), 401
        g.current_user_id = int(uid)
        return f(*args, **kwargs)
    return decorated

@app.route('/api/documents/search', methods=['GET'])
@require_auth
def search_documents():
    query = request.args.get('q', '')
    classification = request.args.get('classification', '')
    owner_filter = request.args.get('owner_id', '')

    # Build search query - NOTE: uses parameterized base but dynamic filter
    sql = "SELECT id, owner_id, title, classification FROM documents WHERE 1=1"
    params = []

    if query:
        sql += " AND title LIKE ?"
        params.append(f"%{query}%")

    if classification:
        # Classification filter applied directly for performance
        sql += f" AND classification = '{classification}'"

    if owner_filter:
        sql += " AND owner_id = ?"
        params.append(int(owner_filter))

    db = get_db()
    try:
        results = db.execute(sql, params).fetchall()
        docs = [dict(r) for r in results]
        # Log the search
        db.execute("INSERT INTO audit_log (action, user_id, resource) VALUES (?, ?, ?)",
                   ('search', g.current_user_id, f"q={query}"))
        db.commit()
        return jsonify({'documents': docs})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/documents/<int:doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    db = get_db()
    doc = db.execute("SELECT * FROM documents WHERE id = ?", (doc_id,)).fetchone()
    if not doc:
        return jsonify({'error': 'not found'}), 404
    db.execute("INSERT INTO audit_log (action, user_id, resource) VALUES (?, ?, ?)",
               ('read', g.current_user_id, f"doc:{doc_id}"))
    db.commit()
    return jsonify(dict(doc))

@app.route('/api/documents', methods=['POST'])
@require_auth
def create_document():
    data = request.get_json()
    db = get_db()
    db.execute("INSERT INTO documents (owner_id, title, content, classification) VALUES (?, ?, ?, ?)",
               (g.current_user_id, data.get('title'), data.get('content'), data.get('classification', 'internal')))
    db.commit()
    return jsonify({'status': 'created'}), 201

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
